def transform(grid):
    out = [row[:] for row in grid]
    markers = [(r, c) for r, row in enumerate(grid) for c, value in enumerate(row) if value == 5]
    if len(markers) < 2:
        return out
    # The 5 embedded in the colored pattern is the source; the isolated 5 is its destination.
    def support(anchor):
        ar, ac = anchor
        return sum(value != 0 and value != 5
                   for r, row in enumerate(grid) for c, value in enumerate(row)
                   if (r, c) != anchor)
    source = max(markers, key=support)
    target = next((p for p in markers if p != source), markers[0])
    sr, sc = source
    tr, tc = target
    for r, row in enumerate(grid):
        for c, value in enumerate(row):
            if value != 0 and value != 5:
                nr, nc = tr + r - sr, tc + c - sc
                if 0 <= nr < len(out) and 0 <= nc < len(out[0]):
                    out[nr][nc] = value
    out[tr][tc] = 0
    return out
